import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

try {
  {operation}
} finally {
  await prisma.$disconnect();
}

const records = await prisma.{model}.findMany({
  where: { {filter} },
  select: { {projection} },
  take: {limit},
});

const result = await prisma.$transaction(async transaction => {
  {operations}
  return {result};
});
